look.customCSS:
/* ───── 红帽夜访 · 第一批 ───── */
[data-wk="chat"]{background:radial-gradient(ellipse at 50% 35%,rgba(90,140,110,.22),transparent 65%),repeating-linear-gradient(90deg,rgba(0,0,0,.42) 0,rgba(0,0,0,.08) 22px,rgba(120,170,140,.10) 40px,rgba(0,0,0,.05) 56px,rgba(0,0,0,.42) 78px),linear-gradient(180deg,#1A3229,#13241E 70%,#0C1814) !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：深木色横梁，底下垂一条红格子布边；顶上一道缝线 */
[data-wk="chathead"]{position:relative !important;background:linear-gradient(180deg,#3A2820,#2A1C15) !important;border-bottom:none !important;box-shadow:0 6px 14px rgba(0,0,0,.45) !important;overflow:visible !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;bottom:-7px !important;height:7px !important;background:url("data:image/svg+xml;base64,") 0 0/8px 8px !important;border-bottom:1px solid #9E2E22 !important;pointer-events:none !important;z-index:2 !important}
[data-wk="chathead"]::before{content:"" !important;position:absolute !important;left:8px !important;right:8px !important;bottom:5px !important;border-bottom:1.5px dashed rgba(242,182,64,.45) !important;pointer-events:none !important}
[data-wk="headink"],[data-wk="headink"] *{color:#FBF3E4 !important;font-family:"Songti SC","Noto Serif SC",serif !important;letter-spacing:.06em !important}
[data-wk="headdim"],[data-wk="headname"] > div:last-child{color:#C9B48F !important;font-style:italic !important}
[data-wk="chatback"] svg{stroke:#FBF3E4 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:26px !important;min-width:26px !important;height:26px !important;flex-shrink:0 !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:auto !important;filter:drop-shadow(0 0 4px rgba(242,182,64,.6)) !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:4px !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
/* 顶栏双头像：小红帽和狼外婆挨着，中间一颗小苹果 */
[data-wk="chathead"] [data-wk="headme"]{display:inline-flex !important;position:relative !important;overflow:visible !important;margin-left:-12px !important;flex-shrink:0 !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img,[data-wk="chathead"] [data-wk="avatar"]{width:32px !important;height:32px !important;min-width:32px !important;flex-shrink:0 !important;aspect-ratio:1 !important;border-radius:50% !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img{box-shadow:0 0 0 2.5px #C2412F,0 0 0 4px #FBF3E4 !important}
[data-wk="chathead"] [data-wk="avatar"]{box-shadow:0 0 0 2.5px #FBF3E4,0 0 0 4px #6F5A50 !important}
[data-wk="chathead"] [data-wk="headme"]::before{content:"" !important;position:absolute !important;left:-9px !important;bottom:-4px !important;width:14px !important;height:14px !important;z-index:3 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="offline"] [data-wk="chathead"] [data-wk="headme"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"]{flex:1 1 auto !important;min-width:84px !important}
[data-wk="chathead"] [data-wk="headname"] > div:last-child{white-space:nowrap !important;overflow:hidden !important;text-overflow:ellipsis !important}

/* 头像：他是一圈奶白蕾丝、顶上两只狼耳朵；我是红斗篷一圈、右上兜尖、下面系白蝴蝶结 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *{border-radius:50% !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]){position:relative !important;overflow:visible !important;box-shadow:0 0 0 3px #FBF3E4,0 0 0 4px #D9C8AE,0 0 0 6px rgba(251,243,228,.55),0 3px 8px rgba(0,0,0,.4) !important}
[data-wk="msg"] button[data-wk="avatar"]::before,[data-wk="cardrow"] [data-wk="avatar"]::before{content:"" !important;position:absolute !important;left:-4px !important;right:-4px !important;top:-12px !important;height:14px !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;z-index:-1 !important;pointer-events:none !important}
[data-wk="msg"][data-me="1"] [data-wk="avatar"],[data-wk="cardrow"][data-me="1"] [data-wk="avatar"]{box-shadow:0 0 0 4px #C2412F,0 0 0 5px #9E2E22,0 3px 8px rgba(0,0,0,.45) !important}
[data-wk="msg"][data-me="1"] [data-wk="avatar"]::before,[data-wk="cardrow"][data-me="1"] [data-wk="avatar"]::before{left:auto !important;right:-10px !important;top:-12px !important;width:20px !important;height:20px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAzMCAzMCc+PHBhdGggZD0nTTIgMjggUTYgOCAyOCAyIFEyNCAxNCAyNiAyOFonIGZpbGw9JyNDMjQxMkYnIHN0cm9rZT0nIzlFMkUyMicvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="msg"][data-me="1"] [data-wk="avatar"]::after,[data-wk="cardrow"][data-me="1"] [data-wk="avatar"]::after{content:"" !important;position:absolute !important;left:calc(50% - 11px) !important;bottom:-12px !important;width:22px !important;height:16px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:2 !important;pointer-events:none !important}

/* 气泡：我是红斗篷布——里面一圈白缝线；他是麻布——左边一条红格子布边 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:10px !important;font-family:"Songti SC","Noto Serif SC",serif !important;letter-spacing:.04em !important;line-height:1.6 !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPSc2JyBoZWlnaHQ9JzYnIHZpZXdCb3g9JzAgMCA2IDYnPjxwYXRoIGQ9J00wIDEuNUg2TTAgNC41SDYnIHN0cm9rZT0ncmdiYSgxMjAsOTAsNjAsLjA3KScvPjxwYXRoIGQ9J00xLjUgMFY2TTQuNSAwVjYnIHN0cm9rZT0ncmdiYSgxMjAsOTAsNjAsLjA1KScvPjwvc3ZnPg==") 0 0/6px 6px,linear-gradient(180deg,#CF4D3A,#9E2E22) !important;color:#FBF3E4 !important;outline:1.5px dashed rgba(251,243,228,.85) !important;outline-offset:-5px !important;box-shadow:0 3px 0 #9E2E22,0 6px 12px rgba(0,0,0,.4) !important;padding:11px 18px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:url("data:image/svg+xml;base64,") left top/8px 8px repeat-y,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPSc2JyBoZWlnaHQ9JzYnIHZpZXdCb3g9JzAgMCA2IDYnPjxwYXRoIGQ9J00wIDEuNUg2TTAgNC41SDYnIHN0cm9rZT0ncmdiYSgxMjAsOTAsNjAsLjA3KScvPjxwYXRoIGQ9J00xLjUgMFY2TTQuNSAwVjYnIHN0cm9rZT0ncmdiYSgxMjAsOTAsNjAsLjA1KScvPjwvc3ZnPg==") 0 0/6px 6px,#F1E6D2 !important;background-clip:border-box !important;color:#3A2A20 !important;border-left:none !important;padding:11px 18px 11px 30px !important;box-shadow:inset 18px 0 0 -0px transparent,0 3px 0 #CDBB9E,0 6px 12px rgba(0,0,0,.35) !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]::before{content:"" !important;position:absolute !important;left:0 !important;top:0 !important;bottom:0 !important;width:16px !important;background:url("data:image/svg+xml;base64,") 0 0/8px 8px !important;border-radius:10px 0 0 10px !important;border-right:1.5px solid rgba(158,46,34,.5) !important;pointer-events:none !important}
[data-wk="bubble"][data-kind="text"]::after{content:none !important}

/* 时间：两边一根蕨叶 */
[data-wk="time"] > span{background:none !important;border:none !important;box-shadow:none !important;color:#A8B5A8 !important;font-family:"Songti SC",serif !important;letter-spacing:.2em !important;font-size:11.5px !important;display:inline-flex !important;align-items:center !important;gap:10px !important}
[data-wk="time"] > span::before,[data-wk="time"] > span::after{content:"" !important;width:52px !important;height:10px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="time"] > span::after{transform:scaleX(-1) !important}
/* 已读：黑里一双发亮的狼眼 */
[data-wk="meta"]{color:#A8B5A8 !important;font-size:10.5px !important;letter-spacing:.1em !important;display:inline-flex !important;align-items:center !important;gap:6px !important}
[data-wk="meta"]::before{content:"" !important;width:34px !important;height:12px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;filter:drop-shadow(0 0 3px rgba(242,182,64,.8)) !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{flex-direction:row-reverse !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:#A8B5A8 !important;padding:2px 0 0 62px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:2px 62px 0 0 !important}
[data-wk="bubble"][data-kind="typing"]{background:#F1E6D2 !important;border:none !important;border-radius:10px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#C2412F !important}

/* 动描：像童话书里的一页——旧纸色斜体，左边一道红墨竖线，没有缝线和格子 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"]{display:block !important;background:linear-gradient(90deg,rgba(242,226,196,.13),rgba(242,226,196,.04)) !important;border:none !important;border-left:2px solid rgba(194,65,47,.75) !important;border-radius:0 !important;box-shadow:none !important;color:#E7D8BC !important;opacity:1 !important;font-family:"Songti SC","Noto Serif SC",serif !important;font-style:italic !important;font-size:13px !important;line-height:1.85 !important;padding:6px 14px !important}
/* 系统提示：一行小字，两头一朵小花饰 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#A8B5A8 !important;font-size:11px !important;font-style:normal !important;letter-spacing:.1em !important}
[data-wk="sysnotetext"]::before{content:"❦ " !important;color:#F2B640 !important}
[data-wk="sysnotetext"]::after{content:" ❦" !important;color:#F2B640 !important}

/* 底栏：深木色篮子边，顶上垂一条红格子布、一道金缝线；左蘑菇加号、中间麻布输入框、右边是送花篮和封蜡信 */
[data-wk="composer"]{position:relative !important;background:linear-gradient(180deg,#2A1C15,#1E140F) !important;border-top:none !important;box-shadow:0 -6px 14px rgba(0,0,0,.45) !important;align-items:center !important;gap:8px !important;overflow:visible !important}
[data-wk="composer"]::before{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:-7px !important;height:7px !important;background:url("data:image/svg+xml;base64,") 0 0/8px 8px !important;border-top:1px solid #9E2E22 !important;pointer-events:none !important}
[data-wk="composer"]::after{content:"" !important;position:absolute !important;left:8px !important;right:8px !important;top:5px !important;border-top:1.5px dashed rgba(242,182,64,.45) !important;pointer-events:none !important}
[data-wk="chatinput"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPSc2JyBoZWlnaHQ9JzYnIHZpZXdCb3g9JzAgMCA2IDYnPjxwYXRoIGQ9J00wIDEuNUg2TTAgNC41SDYnIHN0cm9rZT0ncmdiYSgxMjAsOTAsNjAsLjA3KScvPjxwYXRoIGQ9J00xLjUgMFY2TTQuNSAwVjYnIHN0cm9rZT0ncmdiYSgxMjAsOTAsNjAsLjA1KScvPjwvc3ZnPg==") 0 0/6px 6px,#F1E6D2 !important;border:none !important;border-left:10px solid transparent !important;border-image:url("data:image/svg+xml;base64,") 0 0 0 8 / 0 0 0 10px round !important;border-radius:8px !important;color:#3A2A20 !important;font-family:"Songti SC","Noto Serif SC",serif !important;box-shadow:inset 0 1px 3px rgba(0,0,0,.25) !important}
[data-wk="chatinput"]::placeholder{color:#A08A72 !important}
[data-wk="chatplus"]{width:32px !important;min-width:32px !important;height:32px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="send"]{width:40px !important;min-width:40px !important;height:36px !important;border:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;box-shadow:none !important;opacity:1 !important}
[data-wk="chatreply"]{width:44px !important;min-width:44px !important;height:34px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}

/* ───── 红帽夜访 · 第二批：卡片（形状不动；都是外婆篮子里的麻布，顶上一条红格子布边、里面一圈缝线） ───── */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"]{position:relative !important;overflow:visible !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPSc2JyBoZWlnaHQ9JzYnIHZpZXdCb3g9JzAgMCA2IDYnPjxwYXRoIGQ9J00wIDEuNUg2TTAgNC41SDYnIHN0cm9rZT0ncmdiYSgxMjAsOTAsNjAsLjA3KScvPjxwYXRoIGQ9J00xLjUgMFY2TTQuNSAwVjYnIHN0cm9rZT0ncmdiYSgxMjAsOTAsNjAsLjA1KScvPjwvc3ZnPg==") 0 0/6px 6px,#F1E6D2 !important;border:none !important;border-top:8px solid transparent !important;border-image:url("data:image/svg+xml;base64,") 8 0 0 0 / 8px 0 0 0 round !important;border-radius:10px !important;outline:1.2px dashed rgba(158,46,34,.4) !important;outline-offset:-6px !important;box-shadow:0 3px 0 #CDBB9E,0 8px 16px rgba(0,0,0,.4) !important;color:#3A2A20 !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *,[data-wk="photocard"] *{color:#3A2A20 !important;border-color:rgba(90,60,40,.18) !important}
/* 转账：外婆的信笺——金额红色宋体；收下盖一枚红心封蜡 */
[data-wk="transferamount"],[data-wk="transfercur"]{color:#C2412F !important;font-family:"Songti SC","Noto Serif SC",serif !important}
[data-wk="transferrule"]{border:none !important;height:1px !important;background:rgba(158,46,34,.35) !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:rgba(194,65,47,.06) !important;border-top:1px solid rgba(90,60,40,.15) !important}
[data-wk="transferbtn"]{border-radius:8px !important;font-family:"Songti SC",serif !important}
[data-wk="transferbtn"][data-part="take"]{background:#C2412F !important;color:#FBF3E4 !important;border:none !important;outline:1px dashed rgba(251,243,228,.85) !important;outline-offset:-4px !important}
[data-wk="transferbtn"][data-part="back"]{background:transparent !important;border:1px solid rgba(90,60,40,.3) !important}
[data-wk="transferseal"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important;width:44px !important;height:44px !important;font-size:0 !important;color:transparent !important}
[data-wk="transferseal"] *{opacity:0 !important}
[data-wk="transfercard"][data-status="accepted"] [data-wk="transferseal"]{transform:rotate(-12deg) !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.55 !important}
/* 红包：不是信封——一块红斗篷布，左边探出一顶小红帽；领完布褪色 */
[data-wk="rpcard"]{position:relative !important;overflow:visible !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPSc2JyBoZWlnaHQ9JzYnIHZpZXdCb3g9JzAgMCA2IDYnPjxwYXRoIGQ9J00wIDEuNUg2TTAgNC41SDYnIHN0cm9rZT0ncmdiYSgxMjAsOTAsNjAsLjA3KScvPjxwYXRoIGQ9J00xLjUgMFY2TTQuNSAwVjYnIHN0cm9rZT0ncmdiYSgxMjAsOTAsNjAsLjA1KScvPjwvc3ZnPg==") 0 0/6px 6px,linear-gradient(180deg,#CF4D3A,#9E2E22) !important;border:none !important;border-radius:10px !important;outline:1.5px dashed rgba(251,243,228,.85) !important;outline-offset:-5px !important;box-shadow:0 3px 0 #7A2219,0 8px 16px rgba(0,0,0,.4) !important;padding-left:56px !important}
[data-wk="rpcard"]::before{content:"" !important;position:absolute !important;left:10px !important;top:calc(50% - 21px) !important;width:40px !important;height:42px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;z-index:2 !important}
[data-wk="rpcard"] *{color:#FBF3E4 !important}
[data-wk="rpflap"],[data-wk="rpseal"],[data-wk="rpcorner"]{display:none !important}
[data-wk="rpcard"][data-status="done"]{opacity:.6 !important;filter:saturate(.5) !important}
[data-wk="rpenvelope"]{background:radial-gradient(ellipse at 50% 20%,rgba(242,182,64,.25),transparent 60%),url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPSc2JyBoZWlnaHQ9JzYnIHZpZXdCb3g9JzAgMCA2IDYnPjxwYXRoIGQ9J00wIDEuNUg2TTAgNC41SDYnIHN0cm9rZT0ncmdiYSgxMjAsOTAsNjAsLjA3KScvPjxwYXRoIGQ9J00xLjUgMFY2TTQuNSAwVjYnIHN0cm9rZT0ncmdiYSgxMjAsOTAsNjAsLjA1KScvPjwvc3ZnPg==") 0 0/6px 6px,linear-gradient(180deg,#CF4D3A,#7A2219) !important;border:none !important;outline:2px dashed rgba(251,243,228,.85) !important;outline-offset:-8px !important;border-radius:16px !important;box-shadow:0 12px 30px rgba(0,0,0,.5) !important}
[data-wk="rpenvelope"] [data-wk="rparc"]{background:transparent !important;border:none !important}
[data-wk="rpenvelope"] *{color:#FBF3E4 !important}
[data-wk="rpopenbtn"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;box-shadow:none !important;filter:drop-shadow(0 3px 6px rgba(0,0,0,.4)) !important}
[data-wk="rpopenbtn"] *{opacity:0 !important}
[data-wk="rpamount"]{color:#FBF3E4 !important;font-family:"Songti SC",serif !important}
/* 照片：麻布框里一块夜林小窗；语音：跟气泡一样，我红布他麻布 */
[data-wk="photocard"]{padding:8px 8px 10px !important}
[data-wk="photoface"]{border-radius:6px !important;background:linear-gradient(180deg,#1E3A30,#0E1E18) !important;border:none !important}
[data-wk="photoface"] *{color:#FBF3E4 !important}
[data-wk="photocard"] [data-wk="photohint"]{color:#A08A72 !important}
[data-wk="photoface"] svg{stroke:#F2B640 !important}
[data-wk="voice"][data-me]{background:url("data:image/svg+xml;base64,") left top/8px 8px repeat-y,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPSc2JyBoZWlnaHQ9JzYnIHZpZXdCb3g9JzAgMCA2IDYnPjxwYXRoIGQ9J00wIDEuNUg2TTAgNC41SDYnIHN0cm9rZT0ncmdiYSgxMjAsOTAsNjAsLjA3KScvPjxwYXRoIGQ9J00xLjUgMFY2TTQuNSAwVjYnIHN0cm9rZT0ncmdiYSgxMjAsOTAsNjAsLjA1KScvPjwvc3ZnPg==") 0 0/6px 6px,#F1E6D2 !important;border:none !important;border-radius:10px !important;padding-left:14px !important;box-shadow:0 3px 0 #CDBB9E !important}
